import sys
import heapq

def dijkstra(n, edges, start):
    dist = [float('inf')] * n
    dist[start - 1] = 0
    pq = [(0, start - 1)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, weight in edges[u]:
            if dist[v] > dist[u] + weight:
                dist[v] = dist[u] + weight
                heapq.heappush(pq, (dist[v], v))
    return dist

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    q = int(input[idx + 1])
    s = int(input[idx + 2])
    idx += 3
    edges = [[] for _ in range(n)]
    range_edges = ([[] for _ in range(n)], [[] for _ in range(n)])
    for _ in range(q):
        t = int(input[idx])
        if t == 1:
            v = int(input[idx + 1]) - 1
            u = int(input[idx + 2]) - 1
            w = int(input[idx + 3])
            idx += 4
            edges[v].append((u, w))
        else:
            v = int(input[idx + 1]) - 1
             l = int(input[idx + 2]) - 1
            r = int(input[idx + 3]) - 1
            w = int(input[idx + 4])
            idx += 5
            if t == 2:
                range_edges[0][v].append((l, r, w))
            else:
                range_edges[1][v].append((l, r, w))

    dist = dijkstra(n, edges, s)
    for i in range(n):
        for l, r, w in range_edges[0][i]:
            if dist[i] != float('inf'):
                for j in range(l, r + 1):
                    if dist[j] > dist[i] + w:
                        dist[j] = dist[i] + w
        for l, r, w in range_edges[1][i]:
            if dist[i] != float('inf'):
                for k in range(l, r + 1):
                    if dist[k] > dist[i] + w:
                        dist[k] = dist[i] + w

    result = [str(d if d != float('inf') else -1) for d in dist]
    print(" ".join(result))

main()
